/* ---- 卡片期也要有样式：注入 / 移除（与两个内置模块同一套写法）---- */
function injectModCSS() {
  if (document.getElementById('v3-mod-css-' + MOD_ID)) return;
  const st = document.createElement('style');
  st.id = 'v3-mod-css-' + MOD_ID;
  st.dataset.mod = MOD_ID;
  st.textContent = MOD_CSS;
  (document.head || document.documentElement).appendChild(st);
}
function removeModCSS(force) {
  if (!force && document.querySelector('.v3-card[data-id="' + MOD_ID + '"]')) return;
  const st = document.getElementById('v3-mod-css-' + MOD_ID);
  if (st && st.parentNode) st.parentNode.removeChild(st);
}

/* 面板里的数据索引（模块作用域，卡片期也安全） */
function wpEsc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;')
    .replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function wpEl(tag, cls, html) {
  const e = document.createElement(tag);
  if (cls) e.className = cls;
  if (html != null) e.innerHTML = html;
  return e;
}
function wpYear(y) {
  if (y == null || y === '') return '—';
  const n = Number(y);
  if (!isFinite(n)) return String(y);
  return n < 0 ? '前 ' + Math.abs(n) : String(n);
}

/* 面板里的数据索引（模块作用域，卡片期也安全） */
const P = {};          // 势力名 -> 条目
const PORDER = [];     // 按 DATA 顺序
for (const it of (DATA.polities || [])) {
  if (!it || !it.name) continue;
  P[it.name] = it;
  PORDER.push(it.name);
}
function wpFlat(it) {
  const p = (it.people || []).map(function (x) {
    return (x.name || '') + ' ' + (x.en || '') + ' ' + (x.role || '') + ' ' + (x.life || '');
  }).join(' ');
  const t = (it.terms || []).map(function (x) {
    return (x.name || '') + ' ' + (x.cat || '') + ' ' + (x.d || '');
  }).join(' ');
  const e = (it.events_add || []).map(function (x) { return x.text || ''; }).join(' ');
  return [it.name, it.summary, it.brief_add, p, t, e].filter(Boolean).join(' ');
}

/* 「立即应用 / 撤销补充」按钮在卡片期（未装配）也要能点，
   用模块作用域变量做闸门（不挂全局，遵守「不留裸全局变量」的红线） */
let APPLY_NOW = null;
let UNDO_NOW = null;

/* ============================== 模块主体 ============================== */
let SNAP = null;   // 快照（卸下时回滚）

export default {
  id: MOD_ID,
  name: '世界势力资料补充',
  icon: '界',
  version: '1.0.0',
  author: '',
  description: '为中国以外的全部势力补人物、名词、年表与深度资料，接进既有资料框架，可一键撤回。',

  settingsSchema: [
    { type: 'group', label: '资料并入范围' },
    { type: 'toggle', key: 'people', label: '人物目录并入人物库', default: true,
      hint: '补出的君主 / 将相 / 学者 / 教士 / 艺人写进人物库，势力面板上的名字即可点开，顶部搜索也能搜到' },
    { type: 'toggle', key: 'terms', label: '名词目录并入搜索与正文链接', default: true,
      hint: '制度、事件、典籍、地物、称号写进词条层：正文中出现这些词会自动变成可点链接' },
    { type: 'toggle', key: 'relations', label: '人物关系并入关系图谱', default: true },
    { type: 'toggle', key: 'polity', label: '势力资料与年表增补', default: true,
      hint: '简介增补（追加在原有简介之后）、四维深度资料（只在空缺时填）、名人/统治者标签与年表大事' },
    { type: 'info', text: '补进来的资料<b>只增不改</b>：程序里已经写好的正文一个字都不动。'
      + '卸下模块会按快照原样退回；也可以点下面的「撤销补充」即时撤回。' },
    { type: 'custom', key: '__wpp', render: function (host, io) {
      injectModCSS();
      const box = wpEl('div', 'v3-note');
      function paint() {
        const tot = PORDER.length;
        let pe = 0, te = 0, re = 0, ev = 0;
        for (const n of PORDER) {
          const it = P[n];
          pe += (it.people || []).length;
          te += (it.terms || []).length;
          re += (it.relations || []).length;
          ev += (it.events_add || []).length;
        }
        box.innerHTML = '<div style="line-height:1.7">'
          + '本模块收录 <b>' + tot + '</b> 个势力　·　人物 <b>' + pe + '</b> 位　·　名词 <b>' + te
          + '</b> 条　·　年表大事 <b>' + ev + '</b> 条　·　关系 <b>' + re + '</b> 条<br>'
          + '<span style="opacity:.75">每个势力都设「人物目录」与「名词目录」两类，两类都能被顶部搜索命中，'
          + '正文中出现名词还会自动变成可点链接。中国相关条目由《中国古代历史补充》负责，本模块不重复补。</span></div>';
      }
      paint();
      const row = wpEl('div', '', '');
      row.style.cssText = 'display:flex;gap:6px;margin-top:8px;flex-wrap:wrap';
      const b1 = wpEl('button', 'v3-btn pri', '立即应用');
      const b2 = wpEl('button', 'v3-btn', '撤销补充');
      const hint = function () {
        try { if (__HOST && __HOST.toast) __HOST.toast('请先把模块的开关打开（装配）后再操作', 3000, 'err'); }
        catch (e) { void e; }
      };
      b1.onclick = function () { if (APPLY_NOW) APPLY_NOW(); else hint(); };
      b2.onclick = function () { if (UNDO_NOW) UNDO_NOW(); else hint(); };
      row.appendChild(b1); row.appendChild(b2);
      box.appendChild(row);
      host.appendChild(box);
      return function () { removeModCSS(true); };
    } }
  ],

  init: function (ctx) {
    let gen = 0;
    gen++;
    const later = function (fn, ms) {
      const g = gen;
      return setTimeout(function () { if (g === gen) fn(); }, ms);
    };
    const onS = function (k, def) {
      const v = ctx.settings.get(k);
      return (v === undefined || v === null) ? def : v;
    };
    const nodes = [];      // 自建 DOM 登记
    const offs = [];       // 事件解绑登记
    const docOffs = [];    // window/document 监听登记
    const timers = [];

    /* ---------- 能力探测：没有资料接口就只给面板，不写数据 ---------- */
    const D = globalThis.__V3DATA;
    const canWrite = !!(D && typeof D.addPeople === 'function' && typeof D.patchPolities === 'function');
    if (!canWrite) {
      ctx.toast('这册地图的版本还太旧：资料暂时只能浏览、无法并入——换用最新版的《我，地图和小女仆》就好了', 5200, 'err');
    }

    /* ---------- 写数据 ---------- */
    function toPeople() {
      if (!canWrite) return null;
      const list = [];
      for (const n of PORDER) {
        const it = P[n];
        for (const p of (it.people || [])) {
          if (!p || !p.name) continue;
          list.push({
            name: p.name, en: p.en || '', polity: n, role: p.role || '',
            tags: (p.tags || []).slice(), era: p.era || '',
            birth: (typeof p.birth === 'number' ? p.birth : null),
            death: (typeof p.death === 'number' ? p.death : null),
            birth_approx: !!p.birth_approx, death_approx: !!p.death_approx,
            life: p.life || '', sources: p.sources || it.sources || '',
            deep: (p.bio || p.assess) ? { bio: p.bio || '', assess: p.assess || '' } : undefined
          });
        }
      }
      return list.length ? D.addPeople(list, { enrich: true }) : null;
    }
    function toTerms() {
      if (!canWrite || typeof D.addTerms !== 'function') return null;
      const list = [];
      for (const n of PORDER) {
        const it = P[n];
        for (const t of (it.terms || [])) {
          if (!t || !t.name) continue;
          list.push({
            name: t.name, d: t.d || '', to: t.to || n,
            cat: t.cat || '名词', src: t.src || it.sources || '', polities: [n]
          });
        }
      }
      return list.length ? D.addTerms(list) : null;
    }
    function toRelations() {
      if (!canWrite) return null;
      const list = [];
      for (const n of PORDER) {
        for (const r of (P[n].relations || [])) {
          if (!r || !r.a || !r.b) continue;
          list.push({ a: r.a, b: r.b, kind: r.kind || '同袍', records: (r.records || []).slice(0, 3) });
        }
      }
      return list.length ? D.addRelations(list) : null;
    }
    function toPolities() {
      if (!canWrite) return null;
      const list = [];
      for (const n of PORDER) {
        const it = P[n];
        list.push({
          name: n, brief_add: it.brief_add || '', deep: it.deep || {},
          figures_add: it.figures_add || [], rulers_add: it.rulers_add || [],
          events_add: it.events_add || []
        });
      }
      return D.patchPolities(list);
    }

    function apply(silent) {
      if (!canWrite) return;
      if (!SNAP) SNAP = D.snapshot();
      const r1 = onS('polity', true) !== false ? toPolities() : null;
      const r2 = onS('people', true) !== false ? toPeople() : null;
      const r3 = onS('terms', true) !== false ? toTerms() : null;
      const r4 = onS('relations', true) !== false ? toRelations() : null;
      try { D.refresh(); } catch (e) { void e; }
      if (!silent) {
        const seg = [];
        if (r2) seg.push('人物 +' + r2.added + (r2.filled ? '（补全 ' + r2.filled + '）' : ''));
        if (r3) seg.push('名词 +' + r3.added);
        if (r4) seg.push('关系 +' + r4.added);
        if (r1) seg.push('势力 ' + (r1.notFound ? '未匹配 ' + r1.notFound.length : '已更新'));
        ctx.toast('世界势力资料已并入：' + (seg.join('　·　') || '无'), 3600, 'ok');
      }
      return { polity: r1, people: r2, terms: r3, relations: r4 };
    }
    function undo() {
      if (!canWrite || !SNAP) return;
      try { D.restore(SNAP); } catch (e) { void e; }
      SNAP = null;
      ctx.toast('已撤销本模块补进的全部资料', 3000, 'ok');
    }
    function reapply() {
      undo();
      apply(true);
    }

    /* 面板按钮用得到（卡片期点击 → 走这两个全局闸门） */
    APPLY_NOW = function () { apply(false); };
    UNDO_NOW = function () { undo(); };

    offs.push(ctx.settings.onChange('people', reapply));
    offs.push(ctx.settings.onChange('terms', reapply));
    offs.push(ctx.settings.onChange('relations', reapply));
    offs.push(ctx.settings.onChange('polity', reapply));

    /* ---------- 开工 ---------- */
    apply(true);
    if (!PORDER.length) ctx.toast('世界势力资料补充：没有载入任何条目', 3000, 'err');

    return function dispose() {
      gen++;
      for (const t of timers) clearTimeout(t);
      for (const f of docOffs) { try { f(); } catch (e) { void e; } }
      for (const f of offs) { try { f(); } catch (e) { void e; } }
      for (const nd of nodes) { if (nd && nd.parentNode) nd.parentNode.removeChild(nd); }
      removeModCSS(false);
      try { if (SNAP && canWrite) D.restore(SNAP); } catch (e) { void e; }
      SNAP = null;
    };
  }
};
